mapper.select:
Select atch_file_id as atchFileId -- 파일ID ,atch_file_sno as atchFileSno -- 번호 ,atch_file_path as atchFilePath -- 서버저장Path ,atch_file_ogcp_nm as atchFileOgcpNm -- 화면이름 ,atch_file_sav_nm as atchFileSavNm -- 서버파일이름 ,atch_file_extsn_nm as atchFileExtsnNm -- 확장자 ,atch_file_size_nval as atchFileSizeNval -- 사이즈 ,frst_rgsr_id as frstRgsrId -- 아이디 ,frst_rgst_ip as frstRgstIp -- 아이피 ,to_char(frst_rgst_dt, 'YYYY-MM-DD HH24:MI:SS') as frstRgstDt -- 저장일자 ,last_updr_id as lastUpdrId -- 수정아이디 ,last_updt_ip as lastUpdtIp -- 수정아이피 ,last_updt_dt as lastUpdtDt -- 수정일자 ,to_char(last_updt_dt, 'YYYY-MM-DD HH24:MI:SS') as lastUpdtDt From atch_file_info where 1 = 1
AND atch_file_id = #{atchFileId}
AND to_char(last_updt_dt, 'YYYYMMDD') >= #{fmDate}
AND to_char(last_updt_dt, 'YYYYMMDD') <= #{toDate}
order by last_updt_dt desc, atch_file_id desc
